import type { BlogPost, BlogSection } from './blog';
import { growthRiskGuides } from './growth-risk-guides';
import { growthPracticalGuides } from './growth-practical-guides';
export type Guide = { slug: string; title: string; description: string; keyword: string; category: string; warning: string; sections: BlogSection[]; faq: NonNullable<BlogPost['faq']>; sources: NonNullable<BlogPost['sources']>; related: string[] };
const section = (heading: string, body: string, extra: Partial<BlogSection> = {}): BlogSection => ({ heading, body, ...extra });
const npsTrip = { title: 'National Park Service: planificación de una salida', url: 'https://www.nps.gov/subjects/healthandsafety/trip-planning-guide.htm' };
const npsHike = { title: 'National Park Service: Hike Smart', url: 'https://www.nps.gov/articles/hiking-safety.htm' };
const meteo = { title: 'AEMET: predicción de montaña', url: 'https://www.aemet.es/es/eltiempo/prediccion/montana' };
const guides: Guide[] = [
  {
    slug: 'senderismo-principiantes-planificar-ruta', title: 'Senderismo para principiantes: prepara una ruta que puedas terminar', description: 'Planifica tu primera ruta de senderismo: terreno, desnivel, previsión, equipo y un plan de vuelta sin depender solo del GPS.', keyword: 'senderismo para principiantes', category: 'Montaña y naturaleza',
    warning: 'Esta guía prepara una salida sencilla, no habilita para terreno técnico, nieve, barrancos o vías expuestas. Consulta al gestor del espacio y a profesionales cuando la actividad exceda tu experiencia.',
    sections: [
      section('La primera ruta no debe demostrar nada', 'Una excursión buena no es la más larga de la comarca. Es aquella que puedes disfrutar, comprender y terminar con margen. Si estás empezando, el objetivo es aprender cómo responde tu cuerpo, qué material utilizas de verdad y cómo se organiza el grupo. Llegar agotado al coche no prueba que elegiste bien; puede significar que faltó una alternativa más corta.\n\nEmpieza por una pregunta concreta: ¿qué queremos hacer hoy? Caminar por una zona conocida, aprender a mirar un mapa o pasar tiempo en familia son objetivos distintos. Elige uno y quita complejidad al resto. No estrenes simultáneamente un recorrido exigente, unas botas, una mochila pesada y un horario apretado. Esa combinación hace difícil averiguar qué falló y deja poco margen para corregirlo.'),
      section('Lee la ruta como una sucesión de tramos', 'Una ficha con kilómetros y una fotografía bonita no describe toda la actividad. Divide el itinerario en salida, primer tramo, punto de decisión, regreso y acceso al transporte. En cada parte busca superficie, desnivel, exposición y posibilidades de abandonar. Un camino ancho que asciende despacio no tiene las mismas exigencias que una senda estrecha sobre terreno suelto.\n\nMarca las dudas antes de salir. Si una descripción utiliza expresiones que no comprendes, pregunta al gestor o elige otra opción. No traduzcas automáticamente una clasificación deportiva a tus capacidades. Una ruta popular puede dejar de ser adecuada tras lluvia, obras o cambios de acceso. La experiencia de otra persona tampoco sustituye las condiciones del día en que tú vas a caminar.'),
      section('Una ficha de decisión, no una colección de datos', 'Completa esta tabla con respuestas que puedas comprobar. Si una respuesta sigue siendo una suposición, trátala como una limitación del plan. No hace falta convertir la salida en un expediente: bastan unas pocas referencias claras que otra persona pueda entender sin entrar en tu teléfono.', { table: { caption: 'Ficha preventiva de una primera ruta', headers: ['Pregunta', 'Respuesta que necesitas'], rows: [['¿Dónde empieza y termina?', 'Punto reconocible y acceso permitido'], ['¿Qué tramo puede complicarse?', 'Terreno, pendientes o exposición'], ['¿Dónde podemos volver?', 'Cruce o referencia identificable'], ['¿Qué haría cancelar?', 'Condición acordada, no improvisada'], ['¿Quién conoce el plan?', 'Contacto externo y regreso previsto']] } }),
      section('El grupo importa más que la media de una aplicación', 'Habla de experiencia, ritmo y necesidades sin convertirlo en una competición. La ruta tiene que servir a la persona con menos margen, no al integrante que corre más. Acuerda cómo os reagruparéis y qué haréis si alguien necesita parar. Evita que una persona quede sola por caminar más despacio o por detenerse a ajustar el calzado.\n\nSi vais con menores, prepara una salida que permita terminar antes de que todo resulte una negociación. El interés por explorar no garantiza autonomía para volver. Con personas que tienen tratamientos o limitaciones particulares, consulta previamente qué condiciones necesitan. Una pregunta hecha con respeto en casa evita tomar decisiones delicadas cuando ya hay cansancio y presión por continuar.'),
      section('Mira el tiempo para el lugar y el horario reales', 'Consulta previsiones y avisos oficiales para la zona, no solo el icono del municipio donde aparcas. Revisa también las comunicaciones del espacio natural. Si no sabes interpretar un aviso o la previsión presenta condiciones para las que no estás preparado, cambia de actividad. No conviertas la ausencia de lluvia al salir de casa en una garantía para toda la jornada.\n\nGuarda por escrito la decisión práctica que deriva de la consulta: adelantar la salida, escoger una ruta menor o cancelar. La información meteorológica es útil cuando cambia el plan. Fotografiar una pantalla y después ignorarla no añade seguridad. Revisa de nuevo antes de desplazarte; esa comprobación no sustituye observar el entorno durante la salida.'),
      section('Prepara material por funciones', 'Piensa en orientarte, protegerte, beber, comer, iluminar y comunicar, en lugar de empezar por una lista de compras. Comprueba que el mapa incluye el recorrido, que puedes encontrarlo offline y que la linterna funciona con su alimentación real. Lleva ropa adecuada y una reserva adaptada a las condiciones, no únicamente lo cómodo mientras caminas deprisa.\n\nUna mochila pequeña no debería obligarte a eliminar una función esencial. Tampoco conviene llenarla de objetos que no sabes utilizar. Distribuye el material para localizarlo sin vaciar todo en el suelo y acuerda quién lleva qué. No concentres todos los recursos del grupo en una única persona. Si esa persona se separa o su material falla, el resto necesita alternativas.'),
      section('Haz el ensayo antes del desplazamiento', 'Prueba la mochila durante un paseo corto por un lugar conocido. Ajusta las correas, observa qué roza y comprueba que puedes sacar agua o una capa sin ayuda. Abre el mapa con la conexión temporalmente desactivada en casa y restablécela al terminar. No hagas esa prueba mientras esperas una comunicación importante.\n\nPara comprobar el calzado, utiliza los mismos calcetines que llevarás. Prepara alimentos que ya sabes que toleras y revisa cómo se abrirán los envases. Estos detalles parecen pequeños hasta que varios fallan juntos. La finalidad del ensayo es descubrir problemas baratos de corregir, no reproducir una emergencia ni medir cuánto sufrimiento puedes soportar.'),
      section('Deja un plan comprensible a alguien que no vaya', 'Comunica ruta prevista, participantes, punto de inicio, regreso esperado y cómo avisarás al terminar. Si cambias de recorrido, actualiza el plan cuando sea posible. No prometas un mensaje en un lugar cuya cobertura desconoces. Acuerda una actuación razonable con esa persona si hay retraso, y sigue las recomendaciones de los servicios locales.\n\nUn contacto externo no es un sistema automático de rescate. Es una persona que dispone de información mejor que un simple «vamos al monte». Protege los datos personales: no publiques tu documentación o necesidades médicas en un grupo abierto. Puedes preparar una ficha mínima para el contacto de confianza y conservar la información sensible de forma adecuada.'),
      section('Tres decisiones durante el recorrido', 'En un cruce importante, confirma que reconoces la referencia antes de avanzar. En el punto de retorno, revisa el tiempo real empleado y las condiciones. Si alguien plantea un problema, escúchalo antes de decidir que puede esperar. El esfuerzo ya invertido no obliga a continuar una actividad que ha perdido margen.\n\nVolver por un tramo conocido no siempre será posible ni seguro si cambia el entorno. Por eso conviene revisar alternativas antes de salir. Ante peligro inmediato o necesidad de rescate, pide ayuda al 112 y sigue sus instrucciones. Esta guía no determina a distancia si una senda, un paso o un refugio son adecuados durante una situación real.'),
      section('La salida termina cuando revisas lo aprendido', 'Al volver, avisa al contacto y dedica un momento a anotar tres cosas: qué utilizaste, qué echaste en falta y qué decisión modificarías. Describe hechos, no juicios contra el grupo. «La mochila rozó al bajar» permite hacer una prueba; «soy malo caminando» no ofrece una acción concreta.\n\nGuarda la ficha para la próxima salida, pero no la reutilices sin mirar fecha, accesos y previsión. Cambia una variable cada vez: un recorrido algo más largo o una nueva combinación de ropa, no todo simultáneamente. Esa progresión facilita aprender con margen. La preparación se vuelve una costumbre cuando cada salida deja una comprobación útil para la siguiente.'),
    ],
    faq: [{ question: '¿Cuántos kilómetros debe tener mi primera ruta?', answer: 'No existe una cifra universal. Valora terreno, desnivel, condiciones, ritmo del grupo y posibilidad de acortar. Empieza con una opción que deje margen para volver, no con una distancia que debas completar a cualquier coste.' }, { question: '¿Puedo orientarme solo con el móvil?', answer: 'El móvil puede ayudar si llevas cartografía preparada y batería, pero no elimina errores ni fallos. Aprende referencias del recorrido, conserva una alternativa adecuada y no estrenes la orientación en una zona desconocida.' }, { question: '¿Qué hago si la ruta no coincide con la descripción?', answer: 'No fuerces el paso para encajar el plan. Detente en un lugar seguro, revisa referencias y condiciones y valora regresar o pedir orientación oficial. Si existe peligro o necesitas rescate, contacta con el 112.' }],
    sources: [npsTrip, meteo], related: ['mochila-dia-senderismo-lista', 'hora-retorno-montana', 'brujula-mapa-orientacion-basica'],
  },
  {
    slug: 'hora-retorno-montana', title: 'Hora de retorno en montaña: cuándo dar la vuelta sin improvisar', description: 'Aprende a fijar una hora de retorno para tu ruta: tramos, descansos, luz disponible y decisiones de grupo sin prometer tiempos seguros.', keyword: 'hora de retorno en montaña', category: 'Orientación', warning: 'Un cálculo de horario no acredita seguridad. Terreno técnico, meteorología, lesiones y cambios del entorno pueden exigir cancelar antes. Sigue las instrucciones oficiales y pide ayuda cuando sea necesario.',
    sections: [
      section('Volver es parte de la ruta, no lo que queda después', 'Es fácil preparar el camino hasta un mirador y tratar el regreso como un trámite. El problema aparece cuando el grupo consume el margen antes de alcanzar ese objetivo. La bajada puede requerir atención, las paradas se alargan y una persona que caminaba bien por la mañana puede necesitar un ritmo diferente después. La hora de retorno introduce una decisión acordada antes de que el cansancio o las ganas de llegar condicionen la conversación.\n\nNo es una hora mágica que garantice volver sin incidentes. Es un límite preventivo que debes revisar con otras señales. Si el tiempo cambia, alguien tiene dolor o no reconoces la ruta, esperar a que llegue la hora fijada puede ser un error. El plan sirve para ordenar decisiones, no para posponerlas.'),
      section('Empieza por la hora de llegada que necesitas', 'Anota cuándo debes terminar y por qué: transporte, apertura de un acceso o condiciones de luz que hayas comprobado. Distingue un compromiso externo de una preferencia. Si el coche tiene que salir a una hora concreta, ese límite condiciona la excursión desde el comienzo. No lo soluciones aumentando el ritmo al final.\n\nDespués separa desplazamiento de vuelta, descansos previstos y un margen adicional. El margen no debe convertirse en tiempo que ya cuentas gastar para alcanzar un objetivo. Si toda la jornada está ocupada antes de salir, escoge una ruta más corta. Para empezar no necesitas una estimación perfecta; necesitas reconocer que tu plan tiene condiciones y que debe permitir cambiar de idea.'),
      section('Divide el regreso en partes reconocibles', 'Trabaja con cruces, refugios habilitados, collados o lugares que puedas identificar, sin inventar puntos de seguridad. Para cada tramo anota cómo conocerás su inicio y su final. Si solo escribes «volver al coche», no sabrás dónde se acumula el retraso. Tampoco necesitas un cronómetro para cada piedra: unas pocas referencias bastan para comparar lo previsto con lo observado.\n\nEvita trasladar la duración de una aplicación a cualquier grupo. Revisa qué terreno, desnivel y condiciones describe la estimación. Si no cuentas con experiencia comparable, pregunta a un profesional o reduce la ambición. El tiempo que te costó una caminata por terreno cómodo no valida una senda expuesta, nieve o un descenso técnico.'),
      section('Un ejemplo doméstico para entender el margen', 'Imagina, solo como ejercicio, que quieres terminar a las 17:00. En tu hoja asignas dos horas a la vuelta, media hora a paradas y otra media hora de reserva. La resta sitúa un punto de decisión a las 14:00. Eso no demuestra que esas duraciones sirvan para una ruta real: únicamente muestra cómo hacer visible el tiempo que antes escondías dentro del plan.\n\nAhora cambia una suposición. La vuelta necesita una hora más de lo previsto. El punto de decisión también tiene que adelantarse. Si esa modificación hace imposible el objetivo, la respuesta preventiva es cambiar de recorrido, no eliminar descansos ni la reserva. Practicar con números ficticios en casa ayuda a entender la estructura sin exponer a nadie.'),
      section('Registra el tiempo observado sin convertirlo en una competición', 'En la primera referencia compara el plan con lo ocurrido. Incluye paradas, ajustes de material y dificultades de orientación. Si vas más lento, no supongas automáticamente que recuperarás todo en el siguiente tramo. Comunica al grupo el cambio y revisa la opción corta. Si has llegado antes, no gastes necesariamente todo ese margen ampliando la ruta.\n\nUn registro útil describe condiciones: terreno seco, grupo reducido, mochila ligera o pausas frecuentes. Esos datos explican mejor el resultado que una cifra aislada. No compares personas para presionarlas. La referencia debe permitir que el grupo siga unido y conserve capacidad para tomar decisiones, no señalar quién supuestamente está estropeando el horario.'),
      section('Decide de antemano qué señales adelantan el retorno', 'La hora es solo una de las condiciones. Escribe antes qué cambios harán revisar la actividad: empeoramiento meteorológico, problemas de material, cansancio no previsto o pérdida de referencias. No inventes umbrales médicos para decidir si alguien puede continuar. Escucha la necesidad y pide asistencia profesional cuando corresponda.\n\nAcordad que cualquiera puede plantear una preocupación sin que eso se convierta en una discusión sobre valentía. Una frase sencilla, como «necesito revisar el plan», facilita detener la inercia. Después observad el problema y las alternativas disponibles. Esta práctica es especialmente importante cuando algunos integrantes tienen más experiencia y los demás tienden a seguirlos aunque no estén cómodos.'),
      section('La luz disponible no equivale al tiempo seguro para caminar', 'Consulta la información del lugar y la fecha; no reutilices un horario de otra estación. Las herramientas de horas de luz pueden ayudar a organizar la jornada, pero no describen sombra, visibilidad, exposición o dificultad del camino. Un tramo puede resultar inadecuado antes del ocaso, y llevar frontal no convierte cualquier recorrido nocturno en una alternativa aceptable.\n\nSi no tienes experiencia de noche, planifica para evitar necesitarla. Conserva iluminación como recurso adicional y comprueba cómo funciona. No compenses una salida tardía con la frase «tenemos luz». El objetivo de organizar el tiempo es reducir dependencias, no añadir una condición que nunca has practicado para mantener un itinerario demasiado largo.'),
      section('Una hoja compartida que cabe en el bolsillo', 'Guarda la estructura del horario junto al mapa o la ficha del contacto externo. Utiliza referencias que todos entiendan y evita datos personales innecesarios. Deja una versión en papel si el plan depende de un teléfono. Esta tabla es una propuesta organizativa del proyecto, no una fórmula oficial de seguridad.', { table: { caption: 'Hoja de decisión temporal', headers: ['Dato', 'Qué anotar'], rows: [['Fin previsto', 'Hora, lugar y motivo'], ['Regreso', 'Tramos y supuestos de duración'], ['Paradas', 'Necesidades del grupo'], ['Reserva', 'Tiempo que no asignas al objetivo'], ['Retorno anticipado', 'Cambios que obligan a revisar']] } }),
      section('Qué hacer cuando la hora llega y el objetivo está cerca', 'Este es el momento en que el acuerdo previo tiene más valor. «Falta poco» no permite medir lo que ocurrirá después. Revisa el horario, el grupo y las condiciones sin descontar mentalmente la vuelta. Si el plan preventivo indicaba regresar, respétalo salvo que la situación real exija una actuación distinta por seguridad.\n\nVolver no siempre significa retroceder por el mismo sitio si el entorno ha cambiado. No elijas una alternativa desconocida solo porque parece más rápida. Ante un incidente, explica a los servicios de emergencia dónde estás, qué ha ocurrido y qué recursos tienes; sigue sus indicaciones. El horario es una herramienta de preparación, no un procedimiento de rescate.'),
      section('Aprende del retraso sin normalizarlo', 'Tras avisar de que has terminado, revisa dónde cambió el horario y qué supuesto era débil. Si siempre utilizas la reserva completa, tu estimación necesita ajustes. Anota una mejora comprobable para la próxima salida: salir antes, reducir un tramo o practicar una función del material. No conviertas haber llegado por suerte en evidencia de que el plan era adecuado.\n\nGuarda experiencias comparables, pero revisa cada itinerario desde cero cuando cambian temporada, grupo o terreno. Con el tiempo tendrás referencias propias más útiles que una velocidad universal. La mejor consecuencia de esta guía no es caminar más deprisa, sino saber antes cuándo una actividad deja de encajar en el margen que habías preparado.'),
    ], faq: [{ question: '¿Existe una velocidad universal para calcular una ruta?', answer: 'No. Terreno, desnivel, carga, grupo y condiciones cambian el tiempo. Utiliza estimaciones como supuestos revisables y busca asesoramiento para actividades que no conoces.' }, { question: '¿Si llevo frontal puedo retrasar la vuelta?', answer: 'La frontal es un recurso, no una garantía para cualquier itinerario nocturno. No amplíes el plan por disponer de luz cuando careces de experiencia o existen otros riesgos.' }, { question: '¿Qué pasa si doy la vuelta antes de llegar?', answer: 'Has aplicado una decisión preventiva. Registra la razón y lo aprendido. El destino de la excursión no debe pesar más que las condiciones y el bienestar del grupo.' }], sources: [npsTrip, meteo], related: ['senderismo-principiantes-planificar-ruta', 'calculadora-horas-luz-ruta', 'calculadora-velocidad-necesaria-ruta'],
  },
  {
    slug: 'capas-ropa-senderismo-frio-lluvia', title: 'Ropa por capas para senderismo: prepara frío, viento y lluvia', description: 'Organiza la ropa por capas para senderismo: prueba ajustes, protege la reserva seca y evita confiar toda la salida a una sola prenda.', keyword: 'ropa por capas senderismo', category: 'Montaña y naturaleza', warning: 'La ropa no garantiza protección ante cualquier exposición. Si hay síntomas preocupantes, condiciones que superan tu equipo o necesidad de rescate, busca ayuda y sigue instrucciones profesionales.',
    sections: [
      section('Elige una combinación, no una prenda milagrosa', 'Una chaqueta no trabaja sola. Lo que llevas debajo, la humedad que acumulas, cómo ajusta la mochila y la ropa que puedes añadir al parar forman parte del mismo sistema. En vez de buscar una compra que resuelva cualquier clima, prepara una combinación para una actividad concreta y comprueba que sabes modificarla. La temperatura de casa no es una prueba de las condiciones de una ruta.\n\nDistingue el momento de caminar del de esperar. Puedes salir cómodo y descubrir que, al detenerte, necesitas algo que dejaste en el coche. Organiza la protección pensando también en retrasos y pausas, sin inventar una autonomía térmica. Si la previsión excede tu experiencia, elegir otra actividad es una mejora del plan, no un fallo de vestuario.'),
      section('Tres funciones para ordenar el armario', 'Piensa en una capa junto al cuerpo, una combinación de abrigo y una protección exterior apropiada. Los nombres comerciales ayudan menos que conocer qué función cumple cada elemento y qué límites indica su fabricante. No todas las prendas permiten el mismo ajuste ni se comportan igual cuando están húmedas.\n\nSaca las piezas que ya tienes y explica por qué las llevarías. Si dos prendas duplican una función y ninguna resuelve otra necesidad, revisa la selección. No necesitas empezar por sustituir el armario entero. Puedes descubrir que la mejora más importante consiste en llevar una pieza que ya posees, cambiar la forma de guardarla o elegir una talla compatible con las capas inferiores.'),
      section('Comprueba el conjunto con la mochila puesta', 'Prueba movimientos sencillos: levantar brazos, agacharte, mirar a ambos lados y alcanzar un bolsillo. Hazlo en un lugar seguro, sin convertir la prueba en una actividad técnica. Una capucha que gira sobre los ojos o una manga demasiado corta puede pasar desapercibida mientras estás quieto. Las correas también pueden dificultar el acceso a cremalleras y capas.\n\nRevisa que puedes ponerte una prenda adicional sin desmontar todos los objetos de la mochila. Si una pieza necesita ayuda para cerrarse, tenlo en cuenta antes de ir solo. No pruebes impermeabilidad con métodos que contradigan las instrucciones del fabricante. Esta comprobación busca descubrir problemas de ajuste y manejo; no certifica prestaciones contra una tormenta real.'),
      section('Una reserva seca debe estar realmente protegida', 'Separar una prenda de repuesto del material mojado permite encontrarla cuando la necesitas. Elige un sistema compatible con tu equipo y comprueba cierres, no solo etiquetas. Una funda exterior de mochila y un compartimento interno tienen funciones diferentes; revisa dónde podría entrar agua y qué quedará expuesto al abrir.\n\nNo guardes la reserva tan al fondo que resulte imposible utilizarla durante una parada ordinaria. Evita también mezclarla con envases que puedan derramarse. En casa, prepara y deshaz la mochila una vez para ver si puedes mantener separados los elementos. No hace falta mojar nada para detectar que el cierre está dañado o que siempre apoyas la ropa seca sobre el suelo.'),
      section('Cambiar antes suele ser más fácil que corregir tarde', 'Observa cómo te encuentras y ajusta la ropa sin esperar a que todo sea incómodo. No conviertas un consejo general en una orden de quitar abrigo sin considerar el entorno. Busca un lugar adecuado para organizar el cambio y conserva control sobre las prendas para que no se pierdan con el viento.\n\nAcuerda con el grupo que los ajustes forman parte de la salida. Una persona que necesita detenerse no debería sentir presión por mantener el ritmo. Tampoco hace falta consultar continuamente el teléfono para decidir si puedes usar una capa. La preparación consiste en conocer el equipo, observar condiciones y actuar con margen, sin sustituir las indicaciones profesionales ante una situación de riesgo.'),
      section('Manos, cabeza y pies también entran en el plan', 'Es sencillo centrarse en el torso y olvidar qué necesitas para manipular material, caminar o proteger zonas expuestas. Prueba accesorios con el conjunto completo. Comprueba, por ejemplo, si puedes manejar la iluminación y abrir el recipiente de agua sin perder una pieza o dejarla sobre una superficie insegura.\n\nEl calzado merece una comprobación independiente. Una combinación de calcetines cómoda durante unos minutos puede producir molestias en otra actividad. No estrenes un conjunto completo en una salida exigente. Para necesidades médicas, problemas circulatorios o lesiones recurrentes, consulta a un profesional. Una guía de vestuario no puede recomendar a distancia la misma solución para todas las personas.'),
      section('Qué preguntar antes de comprar', 'Describe tu actividad al consultar una prenda: duración, terreno, estación, frecuencia y experiencia. Pregunta por cuidado, compatibilidad con otras capas, tallas y límites de uso. Un producto que parece excepcional en una fotografía puede no encajar con tu mochila o forma de organizar la actividad.\n\nNo confundas una comparativa documental con una prueba propia de rendimiento. Revisa manual y especificaciones del modelo concreto. Si ya tienes una prenda funcional, apunta primero el problema que quieres resolver antes de comprar otra. «Me cuesta acceder a la ventilación con la mochila» es una necesidad verificable; «quiero algo más profesional» no permite comparar mejoras reales.'),
      section('Haz una matriz sencilla de comprobaciones', 'Utiliza esta tabla como registro personal. No asigna temperaturas seguras a las prendas ni sustituye recomendaciones del fabricante. Completa cada fila con lo que observaste en una práctica sencilla y anota lo que sigue sin estar comprobado.', { table: { caption: 'Prueba de ropa por funciones', headers: ['Función', 'Comprobación', 'Pendiente'], rows: [['Movimiento', 'Con mochila y capas puestas', 'Ajuste que limita'], ['Acceso', 'Abrir cierres y sacar una capa', 'Objeto difícil de alcanzar'], ['Reserva', 'Separación de humedad y derrames', 'Cierre o envoltura'], ['Mantenimiento', 'Leer etiquetas y cuidado', 'Lavado o reparación']] } }),
      section('Un ejemplo para corregir el equipo sin comprar de más', 'Imagina que en una salida corta todo va bien al caminar, pero al parar descubres que tu abrigo extra está en una bolsa junto a una botella con cierre defectuoso. El problema principal no es necesariamente la calidad de la chaqueta. Revisar el recipiente y separar la ropa puede resolver una parte concreta del fallo.\n\nEn otro caso, una persona lleva varias capas pero no puede abrir una cremallera con la mochila puesta. La siguiente práctica puede centrarse en ajuste y manejo, no en añadir volumen. Ambos casos son ejemplos hipotéticos. Sirven para recordar que organizar el equipo requiere observar el sistema completo y que no todas las carencias se corrigen con una compra.'),
      section('Después de la salida: mantenimiento y una sola mejora', 'Sigue las instrucciones de secado, limpieza y almacenamiento del fabricante. No guardes material deteriorado como si continuara listo para salir. Revisa cierres, rozaduras y piezas que faltan antes de devolverlo al lugar habitual. Anota la incidencia junto al equipo para no depender de recordarla dentro de un mes.\n\nEscoge una mejora para la próxima práctica y compruébala en condiciones sencillas. Si el conjunto no resulta adecuado para el plan previsto, modifica la actividad. La ropa por capas es una forma de organizar recursos y ajustes, no una invitación a exponerte a más frío, lluvia o viento del que sabes gestionar. Tu mejor protección puede ser una decisión tomada antes de salir.'),
    ], faq: [{ question: '¿Cuántas capas debo llevar siempre?', answer: 'No hay un número que resuelva cualquier actividad. Organiza funciones, condiciones y posibilidades de ajuste, consulta la documentación del equipo y prepara una reserva adecuada.' }, { question: '¿Una prenda impermeable garantiza mantenerme seco?', answer: 'No garantiza por sí sola el resultado del conjunto. Ajuste, cierres, uso y cuidado importan. Comprueba límites del fabricante y evita utilizar la ropa como justificación para una actividad que supera tu preparación.' }, { question: '¿Puedo comprobar el equipo sin salir con mal tiempo?', answer: 'Sí. Prueba movimientos, accesos, cierres y organización en casa o durante un paseo sencillo. Esas comprobaciones detectan fallos sin exponer a nadie a condiciones adversas.' }], sources: [npsHike, meteo], related: ['mochila-dia-senderismo-lista', 'vivac-emergencia-manta-termica', 'calculadora-sensacion-termica-frio-calor'],
  },
  {
    slug: 'mochila-dia-senderismo-lista', title: 'Mochila de senderismo de un día: lista por funciones y prueba real', description: 'Prepara una mochila para senderismo de un día: agua, orientación, protección y luz. Revisa acceso y peso sin confundirla con un kit de 72 horas.', keyword: 'mochila senderismo un día', category: 'Mochila y equipo', warning: 'Una lista no acredita que puedas realizar una ruta. Adapta el material a condiciones, terreno y necesidades del grupo; evita actividades que superen tu experiencia.',
    sections: [
      section('Una salida corta sigue necesitando un plan', 'La duración prevista no describe todos los problemas posibles. Una parada, un cambio de ruta o una dificultad pueden modificar el uso del material. La mochila de día debe responder a la salida que vas a hacer y conservar margen para cambios razonables. No significa transportar una vivienda entera, sino comprobar funciones esenciales antes de decidir qué objetos pueden quedarse.\n\nEmpieza por el recorrido, las personas y las condiciones. Preparar una mochila genérica primero y buscar después una actividad donde encaje invierte el proceso. Un paseo por un entorno conocido y una jornada en montaña no necesitan la misma selección. Si la ruta requiere material o habilidades que no tienes, reduce la actividad o busca formación adecuada.'),
      section('No confundas mochila de día y reserva familiar', 'Una reserva doméstica puede incluir recipientes y alimentos que nunca llevarías caminando. Una mochila de evacuación tiene objetivos y necesidades distintas de una salida recreativa. Compartir algunos objetos no convierte esos conjuntos en intercambiables. Separa qué guardas en casa, qué llevas a la ruta y qué necesitas para otras situaciones.\n\nEsta distinción evita añadir peso sin función y también evita sacar material crítico de una reserva familiar sin reponerlo. Si utilizas la misma linterna en varios contextos, deja un sistema para saber dónde está. El orden del equipo no debería depender de recordar quién lo cogió la última vez. Una etiqueta o una lista de préstamo doméstica pueden resolver ese problema.'),
      section('Orientación: acceso antes que número de aplicaciones', 'Comprueba que el mapa cubre el recorrido y que sabes encontrar las referencias principales. Si llevas cartografía digital, prepara los recursos antes de salir y prueba su acceso offline desde casa. Una captura parcial puede no mostrar la alternativa que necesitas. Aprende también a leer una referencia adecuada fuera del teléfono.\n\nColoca el material de orientación donde puedas consultarlo sin vaciar la mochila. Una herramienta excelente al fondo de una bolsa cerrada puede resultar poco práctica cuando quieres comprobar un cruce. No estrenes funciones en un lugar desconocido. Practicar antes reduce distracciones y facilita distinguir un fallo del equipo de un error al interpretar el mapa.'),
      section('Agua y comida: necesidades concretas y envases conocidos', 'Prepara recursos adaptados a actividad, condiciones y personas. No conviertas una cifra general de Internet en una pauta individual inflexible. Consulta necesidades particulares con profesionales cuando corresponda y no confíes en encontrar agua utilizable sin haber comprobado la fuente. Un recipiente vacío cuenta como recipiente, no como reserva.\n\nRevisa cómo abrirás y transportarás los alimentos, qué se derrama y qué residuos generarán. Evita estrenar productos cuando desconoces tolerancia o alergias. Llevar opciones conocidas facilita organizar pausas sin depender de cocinar. La comida no reemplaza el descanso ni resuelve por sí sola cualquier malestar. Si alguien no está bien, revisa la situación en lugar de limitarte a ofrecer un alimento.'),
      section('Protección: piensa en caminar y en detenerte', 'Organiza ropa y protección según la salida y la previsión. Conserva accesible lo que podrías necesitar al parar y protege la reserva de humedad y derrames. Comprueba que todo encaja con la mochila puesta: la capacidad del compartimento no demuestra que puedas utilizar la prenda o accesorio con facilidad.\n\nIncluye protección adecuada para exposición solar y condiciones del recorrido, sin convertirla en permiso para ignorar riesgos. Un refugio improvisado o una manta compacta no sustituyen preparación, abrigo suficiente o un alojamiento seguro. Si no sabes cómo utilizar un recurso, incorpora una práctica preventiva o elige una alternativa que sí entiendas antes de depender de él.'),
      section('Luz y comunicación: comprueba toda la cadena', 'La linterna debe funcionar con la alimentación que llevas y ser utilizable por la persona que la necesita. El teléfono requiere carga, cable compatible y contactos accesibles. Tener una batería externa no ayuda si el cable está dañado o si nunca has comprobado que inicia la carga. No concentres todos los recursos del grupo en una sola mochila.\n\nNo prometas cobertura ni alcance de comunicaciones que no puedes verificar. Acuerda un plan compartido y deja información a un contacto externo. Los recursos de comunicación facilitan una tarea, pero no garantizan que llegue ayuda. Ante necesidad de rescate, utiliza el 112 cuando sea posible y sigue las instrucciones; no retrases la petición mientras intentas perfeccionar tu equipo.'),
      section('Cuidados y reparación: selecciona lo que sabes manejar', 'Un botiquín necesita responder a las personas del grupo y al uso previsto. No añadas medicamentos de prescripción ajenos o productos que no sabes utilizar. Consulta la continuidad de tratamientos y conservación con profesionales. La preparación sanitaria no se obtiene comprando una bolsa que promete cubrir cualquier incidencia.\n\nPara pequeñas reparaciones, piensa en problemas realmente observados: una correa, un envase o una prenda. No improvises reparaciones de elementos estructurales o de seguridad crítica con bridas o cinta. Un recurso de reparación temporal puede ayudar a organizar material; no certifica que un equipo dañado siga siendo apto para la actividad. Aprende a reconocer cuándo debe retirarse.'),
      section('Una lista compacta para revisar, no para comprar', 'Marca esta tabla solo después de comprobar la función. Es una propuesta organizativa, no un estándar que garantice seguridad ni una lista exhaustiva para cualquier terreno.', { table: { caption: 'Mochila de día por funciones', headers: ['Función', 'Comprobación práctica'], rows: [['Orientación', 'Abrir mapa y reconocer referencias'], ['Agua y comida', 'Reserva real, envases y necesidades'], ['Protección', 'Conjunto probado y reserva separada'], ['Iluminación', 'Encendido y alimentación'], ['Comunicación', 'Contactos, cable y plan externo'], ['Cuidados', 'Necesidades particulares consultadas']] } }),
      section('Haz la prueba de cargar, caminar y encontrar', 'Coloca el conjunto completo y haz un paseo corto en un entorno conocido. Comprueba ajuste, roces y distribución. Después localiza agua, abrigo, iluminación y mapa sin extender todos los objetos. Si otra persona necesita acceder al material, deja que lo busque también. No presupongas que entenderá tu sistema de bolsillos.\n\nAnota el peso observado si tienes una forma fiable de medirlo, pero evita fijar un máximo universal para cualquier persona. La tolerancia depende del contexto y de necesidades particulares. Si el conjunto resulta inmanejable, revisa ruta y selección, no elimines funciones esenciales al azar. Puedes cambiar de plan para que el material y las capacidades encajen mejor.'),
      section('Después de usarla, vuelve a dejarla lista', 'Vacía residuos, revisa lo consumido, seca según las instrucciones y repón lo necesario. Comprueba que no devuelves a la mochila una linterna descargada o un recipiente abierto. Un equipo preparado hace una semana puede dejar de estar listo tras una salida ordinaria. Registra lo que has retirado para no confundir orden con disponibilidad.\n\nPara mejorar, elige un solo fallo observado y pruébalo antes de la próxima ruta. No conviertas cada revisión en una compra nueva. La mochila útil es la que conoces y puedes manejar, no la que fotografía mejor. Su función es apoyar un plan adecuado; una selección de objetos no sustituye experiencia, información oficial ni decisiones preventivas.'),
    ], faq: [{ question: '¿Qué tamaño de mochila necesito?', answer: 'El tamaño debe acomodar las funciones y la organización de tu salida. Prueba el conjunto completo antes de decidir. Un volumen anunciado no dice cuánto peso toleras ni si llegarás fácilmente al material.' }, { question: '¿Puedo usar la mochila de emergencia de casa?', answer: 'Puedes compartir material cuando encaja, pero revisa objetivos y repón lo que saques. Una reserva doméstica, una evacuación y una excursión de día tienen necesidades distintas.' }, { question: '¿Tengo que llevar todo nuevo?', answer: 'No. Empieza por comprobar recursos disponibles y sus límites. Sustituye lo dañado o inadecuado y compra solo para resolver una función pendiente, no para completar una apariencia.' }], sources: [npsHike, npsTrip], related: ['senderismo-principiantes-planificar-ruta', 'capas-ropa-senderismo-frio-lluvia', 'mochila-emergencia-72-horas-peso-realista'],
  },
];
guides.push(
  {
    slug: 'brujula-mapa-orientacion-basica', title: 'Mapa y brújula para principiantes: aprende a orientarte sin improvisar', description: 'Practica orientación con mapa y brújula en un entorno conocido: referencias, norte, escala y errores habituales sin depender solo del GPS.', keyword: 'orientación con mapa y brújula', category: 'Orientación', warning: 'No aprendas estas técnicas durante una pérdida real ni en terreno expuesto. Esta lectura no sustituye formación práctica ni permite garantizar una ruta segura.',
    sections: [
      section('Antes de seguir una flecha, entiende dónde estás', 'Una brújula puede señalar una dirección, pero no sabe si delante hay un muro, un barranco o un acceso prohibido. Un mapa representa información del terreno, pero no garantiza que todo siga igual. Orientarse consiste en relacionar ambas herramientas con referencias observables y tomar decisiones compatibles con la situación. No es caminar en línea recta hasta que aparezca el destino.\n\nEmpieza en un lugar conocido y sencillo, con posibilidad de terminar la práctica sin esfuerzo adicional. Puedes utilizar un parque o un recorrido corto donde reconozcas cruces y edificios. La meta de esta primera sesión no será llegar lejos: será explicar por qué crees estar en un punto y qué información te falta antes de avanzar.'),
      section('Escoge un mapa que realmente sirva para la tarea', 'Revisa cobertura, escala, fecha y leyenda. Un mapa turístico esquemático puede servir para localizar servicios, pero no describe necesariamente relieve o pequeños caminos. Una imagen muy detallada de una zona mínima tampoco te ayudará a comprender una alternativa que queda fuera de ella. Decide primero qué necesitas reconocer y después elige el recurso.\n\nConserva la atribución y las condiciones de uso del proveedor. Si utilizas un archivo digital, comprueba que puedes abrirlo sin conexión y a los niveles de detalle relevantes. No confundas descargar un mapa con aprender a interpretarlo. La práctica debe incluir tanto encontrar una referencia como entender qué símbolos utiliza y qué elementos no representa.'),
      section('Lee la leyenda antes de crear tus propias suposiciones', 'Localiza cómo se representan caminos, carreteras, agua, curvas de nivel y zonas construidas en ese mapa concreto. No todos los productos presentan exactamente las mismas convenciones. Cuando un símbolo no se entiende, busca su definición; adivinarlo puede cambiar el sentido de una decisión. Una línea dibujada no es necesariamente un itinerario que puedas recorrer.\n\nPara aprender, elige tres elementos que ya conoces y encuentra su representación. Después haz el ejercicio inverso: selecciona una referencia sencilla en el mapa y descríbela sin moverte. Si no sabes explicar cómo reconocerla, todavía no la utilices como único apoyo. Este intercambio entre papel y entorno es más útil que memorizar símbolos sin contexto.'),
section('Distingue norte y referencias sin complicar la primera práctica', 'La información cartográfica puede distinguir norte geográfico, de cuadrícula y magnético. Revisa qué describe el mapa y la documentación de tu brújula. No apliques una corrección de declinación tomada de otra zona o fecha. Si no entiendes el procedimiento, busca formación práctica antes de utilizarlo en una actividad dependiente de precisión.\n\nEn una primera sesión puedes centrarte en reconocer direcciones aproximadas y referencias del entorno, sin convertir eso en navegación técnica. Mantén el equipo según su manual y observa qué ocurre cerca de objetos que puedan alterar la lectura. Una indicación inesperada pide una comprobación; no obliga a cambiar automáticamente de camino para obedecer la aguja.'),
      section('Relaciona una posición con más de una pista', 'Un cruce aislado puede parecerse a otro. Busca un conjunto de referencias: forma del camino, orientación general, presencia de un edificio o relación con una zona de relieve. Si varias pistas no encajan, conserva la duda. No marques tu posición con certeza simplemente porque el mapa y el teléfono parecen mostrar algo familiar.\n\nAnota qué observación apoya cada hipótesis. En un ejemplo preventivo, una persona reconoce un sendero pero no el edificio que esperaba ver. Puede haber interpretado mal el cruce, utilizado cartografía distinta o encontrarse ante un cambio del entorno. La respuesta útil es revisar el conjunto desde un lugar seguro, no seguir avanzando para que el plan termine encajando.'),
      section('Una práctica de cuatro referencias, sin salir a explorar a ciegas', 'Selecciona cuatro puntos reconocibles en una zona que ya sabes recorrer. Puedes preparar la secuencia de antemano y pedir a otra persona que revise las referencias. No uses una prueba de orientación para cruzar terrenos privados, taludes o espacios cerrados. El ejercicio es educativo y debe mantener una alternativa sencilla de regreso.', { steps: ['Localiza el punto inicial en el mapa y describe qué lo identifica.', 'Mira la dirección general del siguiente punto y compara con una referencia real.', 'Recorre únicamente el tramo conocido y permitido, sin cortar camino.', 'Al terminar, registra qué señales coincidieron y cuáles generaron duda.'] }),
      section('El rumbo no decide por ti dónde puedes pasar', 'Conocer una dirección no demuestra que exista un paso. Antes de desplazarte, revisa accesos, terreno y restricciones. Evita tratar un rumbo como una orden de atravesar lo que encuentres. La navegación práctica necesita ajustar el recorrido a lugares permitidos y seguros, y algunas decisiones requieren experiencia que una lectura no proporciona.\n\nSi un obstáculo invalida el plan, no inventes una alternativa fuera de tu capacidad. Vuelve a una referencia conocida cuando la situación lo permita o pide orientación adecuada. Durante una pérdida real, desplazarte sin necesidad puede dificultar la localización. Si requieres rescate, contacta con el 112, explica tu información y sigue sus indicaciones en lugar de ensayar técnicas nuevas.'),
      section('Tres errores que conviene detectar en casa', 'El primero es llevar un mapa que termina antes de la zona necesaria. El segundo, depender de una única pantalla sin haber preparado acceso offline. El tercero, utilizar una brújula sin haber leído su manual. Puedes descubrirlos sin realizar ninguna actividad de riesgo: revisa el material en una mesa, abre las referencias y explica el plan a alguien.\n\nTambién conviene comprobar qué harías si falla uno de los recursos. Tener dos aplicaciones que dependen del mismo teléfono no elimina esa dependencia. Prepara una alternativa apropiada y aprende sus límites. No hace falta coleccionar dispositivos; hace falta que la pérdida de una función no te deje completamente sin forma de interpretar el entorno.'),
      section('Cómo registrar progreso sin fingir que ya dominas la orientación', 'Crea una ficha con fecha, zona conocida, recurso utilizado y dudas. Escribe «reconozco este símbolo» o «puedo localizar estos cuatro puntos», no «sé orientarme en cualquier lugar». Esa diferencia te permite aprender sin ampliar la actividad más de lo que has comprobado. La siguiente sesión puede resolver una sola duda con ayuda de formación adecuada.\n\nRevisa también la calidad de tus referencias. Si has necesitado ayuda continua para entender el mapa, no lo ocultes en el registro. Saber qué no entiendes es una parte valiosa del aprendizaje. No te evalúes por la velocidad de la práctica: entender por qué una referencia encaja resulta más útil que completar el recorrido siguiendo a otra persona.'),
      section('Tu siguiente salida necesita un plan propio', 'Lo aprendido en un parque no habilita automáticamente para montaña, nieve, noche o visibilidad reducida. Cambiar de terreno introduce nuevas necesidades y puede requerir formación presencial. Utiliza la práctica inicial para mejorar preguntas al planificar una ruta, no para sustituir el asesoramiento que todavía necesitas.\n\nAntes de salir, revisa recorrido, grupo, previsión y formas de comunicar el plan. Conserva referencias accesibles y acuerda cuándo daréis la vuelta. Un mapa y una brújula son recursos valiosos cuando forman parte de decisiones preventivas. No eliminan errores ni convierten un lugar desconocido en un terreno adecuado para improvisar.'),
    ], faq: [{ question: '¿El norte del mapa y el de la brújula son siempre iguales?', answer: 'No debes asumirlo. La cartografía puede distinguir referencias diferentes. Consulta leyenda, datos del mapa y manual de la brújula; busca formación para aplicar correcciones en actividades que dependan de precisión.' }, { question: '¿Puedo utilizar el musgo para orientarme?', answer: 'No lo conviertas en referencia principal. Su distribución depende de múltiples condiciones. Utiliza cartografía adecuada, herramientas conocidas y referencias que puedas contrastar.' }, { question: '¿Necesito apagar el GPS para aprender?', answer: 'No es necesario eliminar recursos útiles. Puedes practicar interpretación en una zona conocida y comparar resultados, manteniendo alternativas. No realices experimentos de desconexión durante una emergencia.' }], sources: [npsTrip, { title: 'IGN: recursos de cartografía', url: 'https://www.ign.es/web/ign/portal/cbg-area-cartografia' }], related: ['senderismo-principiantes-planificar-ruta', 'gps-movil-sin-internet-mapas-offline', 'que-hacer-si-te-pierdes-24-horas'],
  },
  {
    slug: 'comida-senderismo-sin-cocinar', title: 'Comida para senderismo sin cocinar: organiza una jornada sin hornillo', description: 'Prepara comida para una ruta sin cocinar: alimentos conocidos, alergias, conservación, envases y una reserva organizada sin raciones universales.', keyword: 'comida senderismo sin cocinar', category: 'Alimentación', warning: 'No es una pauta nutricional individual. Consulta necesidades médicas, alergias y tratamientos con profesionales y respeta conservación y uso indicados en cada etiqueta.',
    sections: [
      section('Empieza por la jornada que vas a hacer', 'Preparar comida no consiste en llenar bolsillos con productos que parezcan deportivos. Describe duración prevista, posibilidad de retraso, condiciones y necesidades de las personas. Después elige alimentos conocidos que puedas transportar y consumir según sus etiquetas. No existe un menú universal que sirva para cualquier actividad, temperatura o estado de salud.\n\nPara una primera salida sencilla, evita depender de cocinar. Esa elección reduce pasos y material, pero no convierte cualquier alimento en adecuado. Revisa conservación, envases y tolerancia. Si habitualmente necesitas una pauta particular, consulta cómo adaptarla antes de hacer una actividad diferente. La improvisación nutricional no añade valor a una excursión preventiva.'),
      section('Alimentos conocidos antes que un experimento', 'Elegir algo que ya consumes permite comprobar con antelación sabor, textura, tolerancia y cómo se abre. Una novedad que resulta incómoda o que no te apetece puede acabar sin utilizarse aunque esté en la mochila. No supongas que un producto presentado como «de emergencia» es automáticamente mejor para tu grupo.\n\nPrepara una pequeña prueba en casa con el envase que llevarás. Comprueba si necesitas utensilios, qué se derrama y dónde quedará el residuo. Si hay menores, pregunta también qué pueden manejar sin ayuda. No conviertas esta prueba en una restricción de comida o agua: únicamente organiza una tarea corriente para reducir problemas durante la salida.'),
      section('La etiqueta decide qué puede ir sin refrigeración', 'Un alimento estable cerrado puede necesitar condiciones diferentes después de abrirse. Revisa indicaciones de conservación, fecha y estado del envase. No determines seguridad por olor, apariencia o el hecho de que otra persona lo transportó de esa manera. Si no puedes mantener las condiciones indicadas, elige otra opción para esa actividad.\n\nEvita presentar una nevera pequeña como garantía de una temperatura mantenida durante cualquier jornada. Si utilizas un sistema de frío, debes conocer su funcionamiento y límites. Esta guía prioriza simplificar el menú, no enseñar a validar una cadena de frío sin medios. Ante un alimento dudoso, busca la información del fabricante o una alternativa adecuada.'),
      section('Organiza pausas que no dependan de un punto ideal', 'Selecciona momentos del recorrido donde, si las condiciones lo permiten, podréis deteneros sin bloquear el paso o exponeros. No des por hecho que un refugio estará abierto, que habrá una mesa o que el grupo llegará a una hora exacta. Conserva acceso a lo que necesitas y revisa el plan si el recorrido cambia.\n\nDistingue una pausa para comer de una respuesta a un problema de salud. Si alguien presenta malestar, no lo resuelvas automáticamente ofreciendo una barrita y continuando. Observa la situación, detén la actividad cuando corresponda y busca ayuda profesional. Los alimentos apoyan una jornada planificada; no sustituyen descanso, hidratación apropiada ni atención ante síntomas preocupantes.'),
      section('Separa el menú previsto de la reserva', 'La reserva debe tener una función y ser utilizable por quien la lleva. Si la colocas donde siempre gastas primero, dejará de ser reserva sin que lo adviertas. Etiqueta mentalmente qué está previsto para las pausas normales y qué conservarás para cambios de plan. No fijes una cantidad universal sin valorar personas, actividad y condiciones.\n\nLa reserva también necesita revisión después de cada salida. Un producto que vuelve a casa no necesariamente conserva las mismas condiciones que antes: revisa envase y almacenamiento según etiqueta. No mantengas durante meses alimentos sueltos en una mochila como si nunca hubieran sufrido calor, humedad o golpes. La organización debe incluir dónde los guardarás entre actividades.'),
      section('Alergias y compartir comida requieren una conversación previa', 'Pregunta por necesidades particulares sin exponer información sensible en un grupo abierto. Comprueba ingredientes y advertencias del producto concreto, incluso cuando el nombre parece familiar. No asumas que todos pueden consumir una opción porque la receta habitual de casa sí les resulta adecuada.\n\nAcuerda cómo separar los alimentos y utensilios si hace falta. Evita presionar a una persona para probar algo o presentar compartir como una obligación. Si alguien dispone de un tratamiento o protocolo prescrito, debe preparar su continuidad con profesionales. Una lista de comida de senderismo no reemplaza ese plan y no debe inventar recomendaciones para una enfermedad específica.'),
      section('Envases y residuos forman parte del equipo', 'Guarda de manera que no se aplasten productos ni se mezcle comida con material que pueda contaminarla. Lleva una forma de reunir envases usados y restos, respetando las reglas del espacio. No dejes residuos porque sean pequeños o parezcan biodegradables. El lugar donde comes no debería quedar distinto por haber pasado tú.\n\nPuedes comprobar el volumen de vuelta en casa: abre el menú de prueba, conserva los envases y mira cómo los organizarías. Ese ejercicio puede mostrar que un producto cómodo de comer ocupa mucho después o que siempre necesitas una bolsa que olvidas. Elegir otro envase o preparar una solución conocida resulta más útil que descubrir el problema durante la ruta.'),
      section('Una tabla para construir tu propio menú', 'Escribe alimentos concretos y las condiciones de su etiqueta. Esta tabla organiza decisiones; no prescribe calorías ni cantidades médicas. Utilízala para detectar dependencias que todavía no has resuelto antes de empaquetar.', { table: { caption: 'Menú sin cocina y sin suposiciones', headers: ['Momento', 'Qué revisar'], rows: [['Antes de salir', 'Comida habitual y necesidades particulares'], ['Pausa prevista', 'Envase, utensilio y conservación'], ['Cambio de plan', 'Reserva separada y accesible'], ['Vuelta a casa', 'Residuos y producto sobrante'], ['Próxima salida', 'Reponer y revisar etiquetas']] } }),
      section('Dos ejemplos para detectar carencias', 'Una familia prepara una jornada breve con alimentos conocidos, pero coloca todos los envases en la mochila de una sola persona. Al reorganizarlo antes de salir descubre que los demás no podrían acceder a nada si esa mochila se separa del grupo. Distribuir recursos según capacidades puede corregir una dependencia sin comprar productos nuevos.\n\nOtro grupo lleva comida suficiente en apariencia, pero todas las opciones necesitan abrirse con un utensilio que nadie ha guardado. La solución preventiva puede ser elegir envases manejables o comprobar el utensilio correcto. Son ejemplos ficticios de organización, no recomendaciones de menús. Te ayudan a revisar la tarea completa, desde preparar hasta recoger residuos.'),
      section('El mejor menú es el que puedes revisar', 'Después de la salida registra qué se consumió, qué quedó y qué resultó incómodo. No evalúes únicamente si había mucha comida. Una opción que nunca pudiste abrir o que requería condiciones no disponibles no cumplió su función. Guarda los aprendizajes sin convertirlos en reglas universales para otros grupos.\n\nAntes de repetir, revisa actividad, fecha, personas y etiquetas. Puedes mantener una base conocida y ajustar lo necesario con asesoramiento adecuado para necesidades particulares. Planificar comida sin cocinar permite una salida más sencilla cuando se hace con criterio. No sirve para ignorar condiciones, forzar una actividad larga ni compensar con alimentos un plan que ya ha perdido margen.'),
], faq: [{ question: '¿Cuántas calorías debo llevar?', answer: 'Esta guía no establece una cifra individual. Las necesidades dependen de actividad y persona. Consulta una pauta profesional cuando exista una condición particular y prepara alimentos conocidos con reserva adaptada al plan.' }, { question: '¿Todo lo envasado aguanta sin frío?', answer: 'No. Lee conservación y condiciones después de abrir. La presentación del producto no sustituye a la etiqueta ni acredita seguridad tras una exposición concreta.' }, { question: '¿Necesito comida liofilizada?', answer: 'No necesariamente. Para una salida sin cocinar puede añadir una dependencia de agua o preparación que querías evitar. Elige por función, tolerancia y conservación, no por aspecto técnico.' }], sources: [{ title: 'AESAN: seguridad alimentaria', url: 'https://www.aesan.gob.es/para-la-ciudadania' }, npsHike], related: ['mochila-dia-senderismo-lista', 'gestion-alimentos-sin-electricidad', 'crisis-cadena-suministro-supermercados-vacios'],
  },
  {
    slug: 'revision-mensual-preparacion-familiar', title: 'Revisión mensual de preparación familiar: qué comprobar sin comprar más', description: 'Organiza una revisión mensual del plan familiar: material usado, contactos, medicación, cambios del hogar y una mejora pequeña que puedas comprobar.', keyword: 'revisión preparación familiar', category: 'Preparación familiar', warning: 'La frecuencia propuesta es un hábito organizativo, no una obligación oficial. Sigue revisiones y conservación de cada producto y las indicaciones profesionales para tratamientos o equipos.',
    sections: [
      section('Una fecha en el calendario vale más que una compra olvidada', 'Comprar una linterna es una acción puntual. Saber que funciona cuando la necesitas exige revisar uso, alimentación y ubicación. Lo mismo ocurre con contactos, envases, documentación y acuerdos familiares. La revisión mensual que proponemos es un hábito del proyecto para mantener visible ese trabajo; no sustituye frecuencias del fabricante ni instrucciones oficiales.\n\nPuedes adaptar el ritmo a tu hogar. Si utilizas material, cambian necesidades o detectas un problema, no esperes a una fecha fija para actuar. La sesión sirve para ordenar lo que sigue pendiente y evitar que la preparación sea una actividad que solo recuerdas cuando aparece una noticia alarmante. No necesitas convertirla en una inspección interminable.'),
      section('Empieza por lo que cambió desde la última revisión', 'Pregúntate si se utilizó material, se movió una caja, cambió un teléfono o una persona necesita apoyo distinto. Anota hechos concretos antes de revisar todos los objetos. Si una batería salió para un viaje, comprueba que volvió y está lista. Si una persona dejó de ser contacto disponible, modifica el acuerdo.\n\nNo rehagas el plan entero cada vez. Distingue cambios de detalles estables para concentrar atención donde importa. Una lista que conserva información antigua parece ordenada pero puede fallar al utilizarla. La revisión debe mejorar la disponibilidad real, no únicamente la apariencia del inventario o el porcentaje de una aplicación.'),
      section('Prueba una función de iluminación y una de comunicación', 'Elige una luz y comprueba su encendido y alimentación en condiciones sencillas. No cortes la electricidad del hogar como ensayo ni manipules instalaciones. Localiza un contacto escrito y verifica que el número sigue siendo válido sin realizar llamadas innecesarias a servicios de emergencia.\n\nAlterna recursos entre sesiones para conocer el conjunto, manteniendo las revisiones indicadas por cada fabricante. Si una prueba falla, escribe una acción y un responsable. «Revisar la linterna» es ambiguo; «comprobar el cable guardado y sustituirlo si está dañado» permite cerrar una tarea. No uses una casilla marcada para ocultar que sigues sin saber por qué falla.'),
      section('Revisa consumibles según sus etiquetas', 'Comprueba fechas, estado del envase, conservación y lo que se ha consumido. No determines una nueva caducidad porque el producto parece estar bien. Organiza reposición y rotación con alimentos habituales que encajen en las necesidades familiares. Una reserva abandonada pierde utilidad aunque su cantidad inicial fuera considerable.\n\nEl agua requiere un plan de almacenamiento y uso adecuado. Revisa recipientes y sigue las instrucciones correspondientes; evita mezclar reservas de usos diferentes sin etiquetarlas. Esta revisión no analiza potabilidad ni certifica que un producto sea seguro. Cuando hay avisos de contaminación, prevalecen las instrucciones sanitarias y no lo que anotaste en una sesión doméstica.'),
      section('Tratamientos y apoyo requieren su propio apartado', 'No reduzcas necesidades de salud a «hay botiquín». Comprueba que la información de tratamiento y contacto profesional está actualizada y que conoces las necesidades de conservación. Si una persona depende de un equipo o asistencia, prepara las preguntas que necesitas consultar con profesionales antes de una incidencia.\n\nNo acumules medicación ni modifiques pautas por tu cuenta. La sesión familiar puede identificar una dependencia, pero no decidir un tratamiento. Pregunta con respeto qué apoyo quiere la persona y quién puede sustituir al responsable habitual. Un plan que requiere siempre a alguien que no estará disponible tiene una carencia organizativa aunque todo el material siga en su sitio.'),
      section('Documentación: acceso útil sin exposición innecesaria', 'Comprueba dónde están los documentos esenciales y quién está autorizado a acceder. No hace falta imprimir toda tu vida ni llevar datos sensibles en una mochila abierta. Puedes utilizar información ficticia para verificar que una carpeta o recurso digital se encuentra y abre correctamente.\n\nUna copia en la nube y una copia accesible sin conexión tienen dependencias diferentes. Asegúrate de entender cuál has preparado. Revisa también las exportaciones y destinatarios cuando compartes archivos. Borrar datos de una aplicación no necesariamente elimina una copia que ya enviaron a otra persona. La preparación debería reducir tanto pérdida de acceso como exposición de información.'),
      section('El plan familiar se practica hablando', 'Elige una pregunta sencilla: quién avisa al contacto, dónde se reúne el grupo cuando sea seguro o quién ayuda a una persona dependiente. Pide que los participantes expliquen el acuerdo con sus palabras. No conviertas la conversación en una alarma falsa ni sorprendas a menores para comprobar su reacción.\n\nSi surgen respuestas distintas, aprovecha para aclararlas. El objetivo no es poner una nota, sino reducir decisiones futuras. Acordad también qué instrucciones oficiales prevalecerán sobre el plan doméstico. Un punto de encuentro previsto puede resultar inseguro durante una incidencia concreta; saber adaptar el acuerdo es tan importante como recordar una dirección.'),
      section('Una ficha que deja claras las próximas acciones', 'Registra solo lo necesario para seguir el trabajo. La tabla propuesta puede usarse en papel y no requiere una cuenta ni enviar datos al sitio. Guarda información sensible por separado y utiliza responsables acordados, no asignados sin hablar.', { table: { caption: 'Registro de revisión doméstica', headers: ['Elemento', 'Resultado', 'Próxima acción'], rows: [['Cambio detectado', 'Qué dejó de coincidir con el plan', 'Actualizar o consultar'], ['Prueba funcional', 'Qué se comprobó realmente', 'Resolver fallo observado'], ['Consumible', 'Estado según etiqueta y uso', 'Reponer o rotar'], ['Acuerdo familiar', 'Duda o responsable ausente', 'Aclarar y preparar sustituto']] } }),
      section('No intentes cerrar veinte tareas el mismo día', 'Elige unas pocas acciones con responsables y forma de comprobarlas. Si la lista crece sin que nada se cierre, revisa si las tareas están suficientemente concretas. «Preparar la casa» es demasiado grande; «poner los contactos acordados en una tarjeta accesible» puede verificarse.\n\nSepara problemas que puedes resolver de dudas que requieren una consulta. Una necesidad sanitaria, un acceso difícil o una instalación dañada no se solucionan añadiendo una compra genérica. Pide el asesoramiento correspondiente. La revisión mejora cuando reconoce límites y evita que un pendiente complejo desaparezca detrás de muchas casillas fáciles de marcar.'),
      section('Cómo saber si este hábito funciona', 'Compara lo que ahora puedes encontrar y utilizar con lo que fallaba antes. Observa si el contacto externo está actualizado, si los materiales vuelven a su lugar y si las personas pueden explicar el acuerdo. No midas preparación solo por número de objetos o litros anotados: esos datos necesitan contexto.\n\nAl final fija la siguiente fecha y una tarea que revisarás. No es una promesa de autonomía ni de respuesta perfecta. Es un mecanismo sencillo para conservar recursos disponibles y aprender de cambios reales. La preparación cotidiana resulta más sostenible cuando se convierte en unas pocas comprobaciones repetibles y no en una carrera continua por comprar más.'),
    ], faq: [{ question: '¿Es obligatorio revisar cada mes?', answer: 'No. Es una propuesta de hábito del proyecto. Revisa además tras usar material, cambiar necesidades y según instrucciones del fabricante o profesionales.' }, { question: '¿Necesito una aplicación para registrar la revisión?', answer: 'No. Una hoja puede servir. La app o una herramienta local son complementos si facilitan el acceso y comprendes dónde se guardan los datos.' }, { question: '¿Cómo evito gastar en cada revisión?', answer: 'Empieza por disponibilidad, manejo y acuerdos. Identifica una función pendiente y decide si reorganizar, practicar, consultar o reponer la resuelve antes de comprar un objeto nuevo.' }], sources: [{ title: 'Protección Civil: Plan Familia Preparada', url: 'https://ficheros.proteccioncivil.es/unidadesFormativas/01_Manal_Plan_Familia_Preparada.pdf' }], related: ['como-revisar-kit-emergencia', 'como-crear-plan-familiar-emergencia', 'documentacion-conviene-tener-disponible'],
  },
);
guides.push(...growthRiskGuides, ...growthPracticalGuides);
const practiceNotes: Record<string, BlogSection> = {
  'comida-senderismo-sin-cocinar': section('Prueba también el regreso del envase', 'Al terminar una prueba de menú, conserva los envases vacíos y comprueba que puedes reunirlos sin ensuciar el material. Esa tarea también forma parte de preparar la salida.'),
  'revision-mensual-preparacion-familiar': section('Conserva un historial pequeño y comprensible', 'Guarda la fecha anterior y el resultado de las acciones que habías acordado. Si una tarea se repite sin resolverse, pregunta qué impide cerrarla y cambia el enfoque. No añadas otra casilla equivalente. Un historial breve puede mostrar una dependencia del hogar mejor que una lista cada vez más larga de objetos.'),
  'fuego-bushcraft-seguro-permisos-yesca': section('La alternativa también puede ser una sesión de aprendizaje', 'Si una formación cancela el fuego por condiciones, pregunta qué parte puede estudiarse sin encendido. Se pueden revisar instrucciones, preparar una ficha de materiales permitidos y explicar cómo se organizaría el cierre de la actividad. No improvises una nueva práctica con llama para compensar la cancelación.\n\nAnota qué fuente confirma las condiciones y cuándo habría que consultarla de nuevo. Utiliza esa información para preparar otra sesión con el instructor, sin asumir que la autorización será permanente. Haber renunciado de forma responsable puede dejar un aprendizaje útil: conoces mejor los límites y puedes explicar por qué una técnica no se realiza ese día.'),
  'hornillo-camping-monoxido-carbono': section('Un ensayo de organización sin combustible ni llama', 'En una mesa adecuada y con el equipo sin utilizar, prepara un menú que no requiera cocción. Describe qué pasos adicionales necesitaría el sistema de cocina: documentación, recursos compatibles, lugar permitido, manejo aprendido y cierre. No conectes combustible como parte de este ejercicio ni realices un encendido en la vivienda.\n\nPide a otra persona que identifique el manual y las preguntas pendientes. Si no podéis explicar una conexión o un accesorio, anotad la consulta para el fabricante o instructor. El ejercicio no valida el funcionamiento ni sustituye una formación. Hace visible qué parte de la tarea seguía dependiendo de una suposición. También puede mostrar que, para esa salida concreta, cocinar no aporta una ventaja suficiente para justificar una dependencia más compleja.'),
};
for (const guide of guides) if (practiceNotes[guide.slug]) guide.sections.push(practiceNotes[guide.slug]);
const knifeGuide = guides.find(guide => guide.slug === 'cuchillo-bushcraft-uso-seguro')!;
knifeGuide.description = 'Revisa necesidad, manual, normativa y formación antes de usar un cuchillo en bushcraft. Prepara la práctica sin cortes hacia el cuerpo ni improvisaciones.';
export const growthArticles: BlogPost[] = guides.map(guide => ({ slug: guide.slug, title: guide.title, excerpt: guide.description, metaDescription: guide.description, seoTitle: guide.title, category: guide.category, image: `/images/editorial/${guide.slug}.webp`, imageAlt: `Diagrama original de ${guide.title}`, date: '14 octubre 2026', publishedAt: '2026-10-14', updatedAt: '2026-10-14', readingTime: '8 min', keywords: [guide.keyword], warning: guide.warning, sections: guide.sections, faq: guide.faq, sources: guide.sources, relatedLinks: guide.related.map(slug => ({ href: `/supervivencia/${slug}`, label: slug.replaceAll('-', ' ') })) }));
